function parsedToolCall(block) {
    if (!('kind' in block) && block.phase === 'preparing')
        return null;
    const cached = parsedCalls.get(block);
    if (cached !== undefined || parsedCalls.has(block))
        return cached ?? null;
    const call = 'kind' in block ? block.call : block;
    if (call === null) {
        parsedCalls.set(block, null);
        return null;
    }
    let value;
    try {
        value = JSON.parse(call.argsRaw);
    }
    catch {
        parsedCalls.set(block, null);
        return null;
    }
    if (typeof value !== 'object' || value === null || Array.isArray(value)) {
        parsedCalls.set(block, null);
        return null;
    }
    const parsed = { name: call.name, args: value };
    parsedCalls.set(block, parsed);
    return parsed;
}

dependencies.recorded:
function recordedAbsolutePath(meta, field) {
    if (meta === null || typeof meta !== 'object' || Array.isArray(meta))
        return undefined;
    const value = meta[field];
    return typeof value === 'string' && isAbsoluteWorkspacePath(value) ? value : undefined;
}

dependencies.paths:
function isWindowsStylePath(value) {
    return /^[A-Za-z]:[/\\]/.test(value) || value.startsWith('\\\\');
}
function isAbsoluteWorkspacePath(path) {
    return path.startsWith('/') || isWindowsStylePath(path);
}

